<?php
session_start();
require __DIR__ . '/config.php';
require_once __DIR__ . '/bracket-bootstrap.php';
if (empty($_SESSION['admin'])) { header('Location: admin-login.php'); exit; }
$db=getDb(); bracketBootstrap($db); bracketEnsureTables($db);
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function teamName(PDO $db,$id){if($id===null)return 'TBD';$s=$db->prepare('SELECT name FROM squadrons WHERE id=?');$s->execute([(int)$id]);return $s->fetchColumn()?:'Unknown';}
function makeId(){return bin2hex(random_bytes(6));}
function syncBracketEvent(PDO $db,array $m,string $bracketName):void{
    $link=$db->prepare('SELECT event_id FROM bracket_score_events WHERE matchup_id=?');$link->execute([$m['id']]);$eventId=$link->fetchColumn();
    if($m['status']!=='completed'||$m['winner_id']===null){if($eventId){$db->prepare('DELETE FROM events WHERE id=?')->execute([$eventId]);$db->prepare('DELETE FROM bracket_score_events WHERE matchup_id=?')->execute([$m['id']]);}return;}
    $points=(float)($m['points']??0);$name=$bracketName.' - Match '.$m['match_number'].' ('.$m['team1_score'].'-'.$m['team2_score'].')';
    if($eventId){$db->prepare('UPDATE events SET squadron_id=?,event_type=?,event_name=?,value=?,points_awarded=?,timestamp=? WHERE id=?')->execute([(int)$m['winner_id'],'bracket',$name,$points,$points,date('c'),$eventId]);}
    else{$db->prepare('INSERT INTO events(squadron_id,event_type,event_name,value,points_awarded,timestamp,created_at) VALUES(?,?,?,?,?,?,?)')->execute([(int)$m['winner_id'],'bracket',$name,$points,$points,date('c'),date('c')]);$new=$db->lastInsertId();$db->prepare('INSERT INTO bracket_score_events(matchup_id,event_id) VALUES(?,?)')->execute([$m['id'],$new]);}
}
$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $a=$_POST['action']??'';$bid=(string)($_POST['bracket_id']??'');
 try{
  if($a==='create'){
   $name=trim($_POST['name']??'');$type=$_POST['bracket_type']??'multi_round';$ids=array_values(array_unique(array_map('intval',$_POST['participant_ids']??[])));
   if($name==='')throw new Exception('Enter a bracket name.');if(!in_array($type,['multi_round','single_round'],true))throw new Exception('Invalid bracket type.');if(count($ids)<2)throw new Exception('Select at least two teams.');
   $valid=array_map('intval',array_column($db->query('SELECT id FROM squadrons')->fetchAll(),'id'));if(array_diff($ids,$valid))throw new Exception('One or more selected teams are invalid.');
   $db->beginTransaction();$now=date('c');$id=makeId();$db->prepare('INSERT INTO brackets(id,name,created_date,updated_at,champion_id,rounds,bracket_type) VALUES(?,?,?,?,?,?,?)')->execute([$id,$name,$now,$now,null,null,$type]);
   $p=$db->prepare('INSERT INTO bracket_participants(bracket_id,squadron_id,seed,created_at) VALUES(?,?,?,?)');foreach($ids as $i=>$sid)$p->execute([$id,$sid,$i+1,$now]);
   if($type==='single_round'){$roundCount=1;$matchCounts=[(int)ceil(count($ids)/2)];$roundNames=['Single Round'];}
   else{$size=1;while($size<count($ids))$size*=2;$roundCount=(int)log($size,2);$matchCounts=[];for($r=1;$r<=$roundCount;$r++)$matchCounts[]=intdiv($size,2**$r);$roundNames=[];for($r=1;$r<=$roundCount;$r++)$roundNames[]=$r===$roundCount?'Final':($r===$roundCount-1?'Semifinal':'Round '.$r);}
   $rids=[];$rs=$db->prepare('INSERT INTO bracket_rounds(bracket_id,round_number,name,created_at) VALUES(?,?,?,?)');foreach($roundNames as $i=>$rn){$rs->execute([$id,$i+1,$rn,$now]);$rids[$i]=(int)$db->lastInsertId();}
   $mids=[];for($r=0;$r<$roundCount;$r++)for($i=0;$i<$matchCounts[$r];$i++)$mids[$r][$i]=makeId();
   $ms=$db->prepare('INSERT INTO bracket_matchups(id,bracket_id,round_id,match_number,team1_id,team2_id,team1_source_matchup_id,team2_source_matchup_id,team1_score,team2_score,winner_id,points,status,next_matchup_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
   for($r=0;$r<$roundCount;$r++)for($i=0;$i<$matchCounts[$r];$i++){
    $t1=$r===0?($ids[$i*2]??null):null;$t2=$r===0?($ids[$i*2+1]??null):null;$src1=$r>0?$mids[$r-1][$i*2]:null;$src2=$r>0?$mids[$r-1][$i*2+1]:null;$next=($type==='multi_round'&&$r<$roundCount-1)?$mids[$r+1][intdiv($i,2)]:null;
    $status=($t1!==null&&$t2!==null)?'ready':(($t1!==null||$t2!==null)?'bye':'pending');$ms->execute([$mids[$r][$i],$id,$rids[$r],$i+1,$t1,$t2,$src1,$src2,null,null,null,0,$status,$next,$now,$now]);
   }
   if($type==='multi_round'){
    // Automatically advance first-round byes so uneven brackets never strand a team.
    for($i=0;$i<$matchCounts[0];$i++){ $m=$db->prepare('SELECT * FROM bracket_matchups WHERE id=?');$m->execute([$mids[0][$i]]);$row=$m->fetch();if(($row['team1_id']===null) xor ($row['team2_id']===null)){ $winner=$row['team1_id']??$row['team2_id'];$db->prepare('UPDATE bracket_matchups SET winner_id=?,status=?,updated_at=? WHERE id=?')->execute([$winner,'bye',date('c'),$row['id']]);if($row['next_matchup_id']){$slot=(($row['match_number']%2)===1)?'team1_id':'team2_id';$db->prepare("UPDATE bracket_matchups SET $slot=?,updated_at=? WHERE id=?")->execute([$winner,date('c'),$row['next_matchup_id']]);}}
    }
   }
   $db->commit();header('Location: admin-brackets.php?bracket_id='.rawurlencode($id));exit;
  }
  if($a==='assign'){$t1=$_POST['team1_id']!==''?(int)$_POST['team1_id']:null;$t2=$_POST['team2_id']!==''?(int)$_POST['team2_id']:null;if($t1!==null&&$t1===$t2)throw new Exception('A matchup cannot use the same team twice.');$db->prepare('UPDATE bracket_matchups SET team1_id=?,team2_id=?,status=?,team1_score=NULL,team2_score=NULL,winner_id=NULL,points=0,updated_at=? WHERE id=? AND bracket_id=?')->execute([$t1,$t2,$t1!==null&&$t2!==null?'ready':'pending',date('c'),$_POST['matchup_id'],$bid]);$message='Teams saved.';}
  if($a==='score'){
   $s1=(int)$_POST['team1_score'];$s2=(int)$_POST['team2_score'];$points=(float)$_POST['points'];if($s1===$s2)throw new Exception('A completed matchup cannot be tied.');$q=$db->prepare('SELECT m.*,b.name bracket_name,b.bracket_type FROM bracket_matchups m JOIN brackets b ON b.id=m.bracket_id WHERE m.id=? AND m.bracket_id=?');$q->execute([$_POST['matchup_id'],$bid]);$m=$q->fetch();if(!$m||$m['team1_id']===null||$m['team2_id']===null)throw new Exception('Both teams must be set before entering a score.');$winner=$s1>$s2?(int)$m['team1_id']:(int)$m['team2_id'];$db->beginTransaction();$db->prepare("UPDATE bracket_matchups SET team1_score=?,team2_score=?,winner_id=?,points=?,status='completed',updated_at=? WHERE id=? AND bracket_id=?")->execute([$s1,$s2,$winner,$points,date('c'),$m['id'],$bid]);$m['team1_score']=$s1;$m['team2_score']=$s2;$m['winner_id']=$winner;$m['points']=$points;$m['status']='completed';syncBracketEvent($db,$m,$m['bracket_name']);
   if($m['bracket_type']==='multi_round'&&$m['next_matchup_id']){$q=$db->prepare('SELECT * FROM bracket_matchups WHERE id=? AND bracket_id=?');$q->execute([$m['next_matchup_id'],$bid]);$n=$q->fetch();if($n){$slot=((int)$m['match_number']%2===1)?'team1_id':'team2_id';$db->prepare("UPDATE bracket_matchups SET $slot=?,updated_at=? WHERE id=? AND bracket_id=?")->execute([$winner,date('c'),$n['id'],$bid]);$ready=$slot==='team1_id'?($n['team2_id']!==null):($n['team1_id']!==null);if($ready)$db->prepare('UPDATE bracket_matchups SET status=? WHERE id=? AND bracket_id=?')->execute(['ready',$n['id'],$bid]);}}
   if($m['next_matchup_id']===null)$db->prepare('UPDATE brackets SET champion_id=?,updated_at=? WHERE id=?')->execute([$winner,date('c'),$bid]);else $db->prepare('UPDATE brackets SET updated_at=? WHERE id=?')->execute([date('c'),$bid]);$db->commit();$message='Score saved; '.$teamName($db,$winner).' receives '.$points.' bracket points.';
  }
  if($a==='delete'){$ids=$db->prepare('SELECT event_id FROM bracket_score_events WHERE matchup_id IN (SELECT id FROM bracket_matchups WHERE bracket_id=?)');$ids->execute([$bid]);foreach($ids->fetchAll(PDO::FETCH_COLUMN) as $eid)$db->prepare('DELETE FROM events WHERE id=?')->execute([$eid]);$db->prepare('DELETE FROM brackets WHERE id=?')->execute([$bid]);header('Location: admin-brackets.php');exit;}
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}
}
$all=$db->query('SELECT id,name,bracket_type,updated_at FROM brackets ORDER BY updated_at DESC')->fetchAll();$bid=(string)($_GET['bracket_id']??$_POST['bracket_id']??($all[0]['id']??''));$bracket=$bid?bracketLoad($db,$bid):null;$teams=$db->query('SELECT id,name FROM squadrons ORDER BY id')->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Brackets</title><style>body{font-family:Arial;background:#eef1f5;margin:0;color:#182334}.wrap{max-width:1400px;margin:auto;padding:24px}.card{background:#fff;border-radius:10px;padding:20px;margin-bottom:18px;box-shadow:0 2px 8px #0001}.layout{display:grid;grid-template-columns:310px 1fr;gap:18px}.bracket{display:block;padding:11px;border-radius:6px;text-decoration:none;color:#182334}.active{background:#e7edf6;font-weight:bold}.input,select{width:100%;padding:9px;border:1px solid #ccd2db;border-radius:5px;box-sizing:border-box}.picks{display:grid;grid-template-columns:1fr 1fr;gap:6px}.pick{padding:8px;background:#f5f6f8;border-radius:5px}.rounds{display:flex;gap:16px;overflow-x:auto}.round{min-width:290px}.match{background:#f8f9fb;border:1px solid #dce1e8;border-radius:8px;padding:12px;margin:14px 0}.btn{padding:9px 13px;border:0;border-radius:6px;background:#12355b;color:#fff;cursor:pointer}.danger{background:#a52222}.muted{color:#6b7685;font-size:.9em}.msg{color:#176b3b}.err{color:#a52222}.scores{display:flex;gap:6px;align-items:center}.score{width:65px;padding:8px}.type{font-size:.8em;text-transform:uppercase;color:#667}</style></head><body><div class="wrap"><div class="card"><h1>Manage Brackets</h1><p class="muted">Create either a multi-round elimination bracket or a single-round set of matchups. Completed winners award the bracket points entered on the matchup and appear in the scoring history.</p><?php if($error):?><p class="err"><?php echo h($error);?></p><?php endif;?><?php if($message):?><p class="msg"><?php echo h($message);?></p><?php endif;?></div><div class="layout"><aside><div class="card"><h2>Brackets</h2><?php foreach($all as $b):?><a class="bracket <?php echo $b['id']===$bid?'active':'';?>" href="?bracket_id=<?php echo h($b['id']);?>"><?php echo h($b['name']);?><br><span class="type"><?php echo $b['bracket_type']==='single_round'?'Single Round':'Multi-Round';?></span></a><?php endforeach;?></div><div class="card"><h2>New Bracket</h2><form method="post"><input type="hidden" name="action" value="create"><input class="input" name="name" placeholder="Bracket name" required><p><select name="bracket_type" required><option value="multi_round">Multi-Round Elimination</option><option value="single_round">Single Round</option></select></p><p class="muted">Multi-round brackets advance winners through rounds. Single-round brackets create independent matchups with no advancement.</p><div class="picks"><?php foreach($teams as $t):?><label class="pick"><input type="checkbox" name="participant_ids[]" value="<?php echo (int)$t['id'];?>"> <?php echo h($t['name']);?></label><?php endforeach;?></div><p><button class="btn">Create Bracket</button></p></form></div></aside><main><?php if(!$bracket):?><div class="card"><h2><?php echo $all?'Select a bracket':'Create your first bracket';?></h2></div><?php else:?><div class="card"><h2><?php echo h($bracket['name']);?></h2><p class="type"><?php echo $bracket['bracket_type']==='single_round'?'Single Round':'Multi-Round Elimination';?></p><?php if(!empty($bracket['champion_id'])):?><p><strong>Champion:</strong> <?php echo h(teamName($db,$bracket['champion_id']));?></p><?php endif;?><div class="rounds"><?php foreach($bracket['rounds'] as $round):?><section class="round"><h3><?php echo h($round['name']);?></h3><?php foreach($round['matchups'] as $m):?><div class="match"><div class="muted">Match <?php echo (int)$m['match_number'];?> · <?php echo h($m['status']);?></div><form method="post"><input type="hidden" name="action" value="assign"><input type="hidden" name="bracket_id" value="<?php echo h($bid);?>"><input type="hidden" name="matchup_id" value="<?php echo h($m['id']);?>"><p><select name="team1_id"><option value="">TBD</option><?php foreach($teams as $t):?><option value="<?php echo (int)$t['id'];?>" <?php echo (string)$m['team1_id']===(string)$t['id']?'selected':'';?>><?php echo h($t['name']);?></option><?php endforeach;?></select></p><p><select name="team2_id"><option value="">TBD</option><?php foreach($teams as $t):?><option value="<?php echo (int)$t['id'];?>" <?php echo (string)$m['team2_id']===(string)$t['id']?'selected':'';?>><?php echo h($t['name']);?></option><?php endforeach;?></select></p><button class="btn">Save Teams</button></form><?php if($m['team1_id']!==null&&$m['team2_id']!==null):?><p><?php echo h(teamName($db,$m['team1_id']));?>: <?php echo $m['team1_score']===null?'—':(int)$m['team1_score'];?></p><p><?php echo h(teamName($db,$m['team2_id']));?>: <?php echo $m['team2_score']===null?'—':(int)$m['team2_score'];?></p><?php if($m['status']!=='completed'):?><form method="post" class="scores"><input type="hidden" name="action" value="score"><input type="hidden" name="bracket_id" value="<?php echo h($bid);?>"><input type="hidden" name="matchup_id" value="<?php echo h($m['id']);?>"><input class="score" type="number" min="0" name="team1_score" placeholder="T1" required><input class="score" type="number" min="0" name="team2_score" placeholder="T2" required><input class="score" type="number" min="0" step="0.01" name="points" value="0" title="Bracket points awarded to winner"><button class="btn">Save Score</button></form><?php else:?><p><strong>+<?php echo h($m['points']);?> bracket points</strong> to <?php echo h(teamName($db,$m['winner_id']));?></p><?php endif;?><?php endif;?></div><?php endforeach;?></section><?php endforeach;?></div><form method="post" onsubmit="return confirm('Delete this bracket and its bracket score events?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="bracket_id" value="<?php echo h($bid);?>"><button class="btn danger">Delete Bracket</button></form></div><?php endif;?></main></div></div></body></html>
